-- ES/DE/FR translations of the system/desc/actions fields for the 7
-- Slovenia + Iceland milestones defined (in English) by migrations 413
-- and 415. Drafted in drafts/, spot-checked for accuracy against 413/415,
-- then renumbered into migrations/ as file 420. milestone_translations
-- has a natural PK on (milestone_id, lang), so these are plain
-- INSERT OR IGNORE rows keyed on the hardcoded milestone id strings from
-- 413/415 -- no JOIN lookup needed. Every proper noun, law name
-- (ZOPSPU/ZOPSPU-A, ZIERDED, Regulation 44/2019), article number, date,
-- and EUR figure is preserved unchanged from the English source; only
-- the surrounding prose is translated.

-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-b2g-2015', 'es', 'Mandato ZOPSPU: el sector público debe recibir facturas electrónicas', 'Desde el 1 de enero de 2015, el sector público esloveno está obligado a recibir facturas exclusivamente en formato electrónico, en virtud de la Ley de Servicios de Pago para Usuarios Presupuestarios (ZOPSPU / ZOPSPU-A). UJP (la Administración de la República de Eslovenia para Pagos Públicos) opera el hub central obligatorio -- la "enotna vstopna in izstopna točka" (EVIT, punto único de entrada y salida) -- a través del cual los usuarios presupuestarios intercambian facturas electrónicas, accesible mediante bancos participantes, procesadores de datos contratados, o el propio portal e-Racuni de UJP para los proveedores que no disponen de ninguno de los dos.', '["Confirme que su empresa envía las facturas a los compradores del sector público esloveno a través de un banco, un procesador contratado por UJP, o el portal e-Racuni de UJP -- no en papel ni en un PDF simple.", "Si factura directamente a usuarios presupuestarios sin un banco o procesador, regístrese para obtener acceso al portal e-Racuni de UJP."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-zierded-enacted', 'es', 'Se promulga la ZIERDED -- la primera ley eslovena de facturación electrónica B2B', 'La Zakon o izmenjavi elektronskih računov in drugih elektronskih dokumentov (ZIERDED) -- la primera ley eslovena de facturación electrónica B2B obligatoria -- se publicó en el Diario Oficial (Uradni list RS, št. 85/2025). Se aplica a toda entidad inscrita en el Registro Mercantil de Eslovenia y a toda persona autónoma (art. 7), establece un despliegue en dos etapas (proveedores certificados de vía electrónica desde el 1 de abril de 2027, la obligación central de intercambio desde el 1 de enero de 2028), y el art. 1 vincula explícitamente la ley a la transposición de elementos de la directiva ViDA de la UE (2025/516).', '["Lea el texto oficial de la ZIERDED para entender cuál de los tres canales de intercambio permitidos -- proveedor certificado de vía electrónica, enlace directo de sistema a sistema, o Peppol -- se ajusta a su empresa.", "Tenga en cuenta las dos fechas de entrada en vigor independientes: el 1 de abril de 2027 para la certificación de proveedores de vía electrónica, y el 1 de enero de 2028 para la obligación de intercambio propiamente dicha."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-epath-providers-2027', 'es', 'Entra en vigor el régimen de proveedores certificados de "vía electrónica"', 'Las normas del capítulo 4 de la ZIERDED para los proveedores certificados de vía electrónica ("e-pot") se aplican desde esta fecha -- uno de los tres canales permitidos, junto con el intercambio directo de sistema a sistema y Peppol, para el intercambio conforme de facturas electrónicas y documentos electrónicos, antes de la fecha de la obligación general del 1 de enero de 2028.', '["Si tiene previsto usar un proveedor certificado de vía electrónica en lugar de Peppol o un enlace directo de sistema a sistema, confirme que el proveedor elegido cuenta con la certificación bajo este régimen antes de confiar en él."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-b2b-mandatory-2028', 'es', 'Comienza el intercambio obligatorio de facturas electrónicas B2B', 'Entra en vigor la obligación central de la ZIERDED: toda entidad inscrita en el Registro Mercantil de Eslovenia y toda persona autónoma debe intercambiar facturas electrónicas y otros documentos electrónicos a través de uno de los tres canales permitidos por la ley -- proveedor certificado de vía electrónica, enlace directo de sistema a sistema, o Peppol -- con el formato del estándar e-SLOG 2.0 (alineado con la norma EN 16931). El incumplimiento conlleva multas bajo el art. 24: 1.000-3.000 € para personas jurídicas, 500-1.500 € para empresarios individuales, 100-500 € para una persona responsable, con un rango independiente y más bajo bajo el art. 25 para las infracciones relativas a facturas de consumo.', '["Confirme que su software o proveedor de facturación puede generar facturas electrónicas conformes con e-SLOG 2.0 / EN 16931.", "Elija y pruebe uno de los tres canales de intercambio permitidos bien antes del 1 de enero de 2028.", "Confirme que su proceso de cuentas por pagar puede recibir y procesar las facturas electrónicas entrantes a través de los mismos canales."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-reg44-2019', 'es', 'Se publica el Reglamento 44/2019', 'El Ministerio de Finanzas y Asuntos Económicos de Islandia (Fjármála- og efnahagsráðuneytið) emitió el Reglamento 44/2019 (reglugerð um rafræna reikninga vegna opinberra samninga), publicado en el diario oficial Stjórnartíðindi. Transpone la Directiva 2014/55/UE de la UE a través de la pertenencia de Islandia al EEE, y exige que los compradores del sector público reciban y procesen facturas electrónicas conformes con la norma europea EN 16931.', '["Confirme si su empresa suministra bienes, servicios u obras a un organismo público islandés bajo un contrato de contratación pública, servicios públicos, concesión, o defensa/seguridad cubierto por el reglamento."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-b2g-state-2019', 'es', 'Las instituciones estatales deben recibir facturas electrónicas conformes con EN 16931', 'Las instituciones estatales islandesas quedaron obligadas a poder recibir y procesar facturas electrónicas conformes con la norma europea EN 16931. Fjársýsla ríkisins (la Autoridad de Gestión Financiera) recibe facturas electrónicas en representación de la mayoría de las instituciones estatales, a través de la red Peppol.', '["Si factura a una institución estatal islandesa, confirme que canaliza las facturas electrónicas a través de Fjársýsla ríkisins y envíelas en consecuencia, en lugar de en papel o PDF."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-b2g-municipal-2020', 'es', 'Los municipios y las empresas públicas se incorporan al mandato', 'El requisito de recepción de facturas electrónicas se extendió a los municipios, sus instituciones, las empresas públicas, y otras entidades que operan bajo derechos especiales o monopolios, completando así el despliegue del Reglamento 44/2019 en todo el sector público islandés.', '["Si factura a un municipio o empresa pública islandesa, confirme que puede recibir facturas electrónicas conformes con EN 16931 y compruebe si utiliza Fjársýsla ríkisins o su propio punto de acceso Peppol."]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-b2g-2015', 'de', 'ZOPSPU-Pflicht: Der öffentliche Sektor muss elektronische Rechnungen empfangen', 'Seit dem 1. Januar 2015 ist der öffentliche Sektor Sloweniens verpflichtet, Rechnungen ausschließlich in elektronischer Form zu empfangen, nach dem Gesetz über Zahlungsdienste für Haushaltsnutzer (ZOPSPU / ZOPSPU-A). UJP (die Verwaltung der Republik Slowenien für öffentliche Zahlungen) betreibt den verpflichtenden zentralen Hub -- die "enotna vstopna in izstopna točka" (EVIT, einheitliche Ein-/Ausgangsstelle) --, über den Haushaltsnutzer elektronische Rechnungen austauschen, erreichbar über teilnehmende Banken, beauftragte Datenverarbeiter, oder das eigene e-Racuni-Portal von UJP für Lieferanten ohne beides.', '["Bestätigen Sie, dass Ihr Unternehmen Rechnungen an slowenische öffentliche Käufer über eine Bank, einen von UJP beauftragten Verarbeiter oder das e-Racuni-Portal von UJP einreicht -- nicht per Papier oder einfachem PDF.", "Falls Sie Haushaltsnutzer direkt ohne Bank oder Verarbeiter in Rechnung stellen, registrieren Sie sich für den Zugang zum e-Racuni-Portal von UJP."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-zierded-enacted', 'de', 'ZIERDED erlassen -- Sloweniens erstes B2B-E-Rechnungsgesetz', 'Das Zakon o izmenjavi elektronskih računov in drugih elektronskih dokumentov (ZIERDED) -- Sloweniens erstes verpflichtendes B2B-E-Rechnungsgesetz -- wurde im Amtsblatt veröffentlicht (Uradni list RS, št. 85/2025). Es gilt für jede im slowenischen Handelsregister eingetragene Einheit und jede selbstständige Person (Art. 7), legt eine zweistufige Einführung fest (zertifizierte E-Weg-Anbieter ab 1. April 2027, die zentrale Austauschpflicht ab 1. Januar 2028), und Art. 1 verknüpft das Gesetz ausdrücklich mit der Umsetzung von Elementen der ViDA-Richtlinie der EU (2025/516).', '["Lesen Sie den offiziellen Text der ZIERDED, um zu verstehen, welcher der drei zulässigen Austauschkanäle -- zertifizierter E-Weg-Anbieter, direkte System-zu-System-Verbindung, oder Peppol -- zu Ihrem Unternehmen passt.", "Beachten Sie die zwei separaten Stichtage: 1. April 2027 für die Zertifizierung von E-Weg-Anbietern, 1. Januar 2028 für die verpflichtende Austauschpflicht selbst."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-epath-providers-2027', 'de', 'Regime für zertifizierte "E-Weg"-Anbieter tritt in Kraft', 'Die Regeln des Kapitels 4 der ZIERDED für zertifizierte E-Weg-Anbieter ("e-pot") gelten ab diesem Datum -- einer von drei zulässigen Kanälen, neben dem direkten System-zu-System-Austausch und Peppol, für den konformen Austausch von E-Rechnungen und elektronischen Dokumenten vor dem Stichtag der allgemeinen Pflicht am 1. Januar 2028.', '["Falls Sie statt Peppol oder einer direkten System-zu-System-Verbindung einen zertifizierten E-Weg-Anbieter nutzen möchten, bestätigen Sie, dass Ihr gewählter Anbieter über eine Zertifizierung unter diesem Regime verfügt, bevor Sie sich darauf verlassen."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-b2b-mandatory-2028', 'de', 'Verpflichtender B2B-E-Rechnungsaustausch beginnt', 'Die zentrale Pflicht der ZIERDED tritt in Kraft: Jede im slowenischen Handelsregister eingetragene Einheit und jede selbstständige Person muss elektronische Rechnungen und andere elektronische Dokumente über einen der drei vom Gesetz zugelassenen Kanäle austauschen -- zertifizierter E-Weg-Anbieter, direkte System-zu-System-Verbindung, oder Peppol -- formatiert nach dem Standard e-SLOG 2.0 (an EN 16931 angelehnt). Nichteinhaltung zieht Bußgelder nach Art. 24 nach sich: 1.000-3.000 € für juristische Personen, 500-1.500 € für Einzelunternehmer, 100-500 € für eine verantwortliche Person, mit einem eigenen, niedrigeren Bußgeldrahmen nach Art. 25 für Verstöße bei Verbraucherrechnungen.', '["Bestätigen Sie, dass Ihre Rechnungssoftware oder Ihr Anbieter e-SLOG-2.0-/EN-16931-konforme E-Rechnungen erzeugen kann.", "Wählen und testen Sie einen der drei zulässigen Austauschkanäle rechtzeitig vor dem 1. Januar 2028.", "Bestätigen Sie, dass Ihr Kreditorenprozess eingehende E-Rechnungen über dieselben Kanäle empfangen und verarbeiten kann."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-reg44-2019', 'de', 'Verordnung 44/2019 veröffentlicht', 'Islands Ministerium für Finanzen und Wirtschaftsangelegenheiten (Fjármála- og efnahagsráðuneytið) erließ die Verordnung 44/2019 (reglugerð um rafræna reikninga vegna opinberra samninga), veröffentlicht im Amtsblatt Stjórnartíðindi. Sie setzt die EU-Richtlinie 2014/55/EU über Islands EWR-Mitgliedschaft um und verpflichtet öffentliche Auftraggeber, elektronische Rechnungen zu empfangen und zu verarbeiten, die dem europäischen Standard EN 16931 entsprechen.', '["Bestätigen Sie, ob Ihr Unternehmen einer isländischen öffentlichen Stelle Waren, Dienstleistungen oder Bauleistungen im Rahmen eines von der Verordnung erfassten Vergabe-, Versorgungs-, Konzessions- oder Verteidigungs-/Sicherheitsvertrags liefert."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-b2g-state-2019', 'de', 'Staatliche Institutionen müssen EN-16931-E-Rechnungen empfangen', 'Isländische staatliche Institutionen wurden verpflichtet, elektronische Rechnungen empfangen und verarbeiten zu können, die dem europäischen Standard EN 16931 entsprechen. Fjársýsla ríkisins (die Finanzverwaltungsbehörde) empfängt elektronische Rechnungen im Auftrag der meisten staatlichen Institutionen über das Peppol-Netzwerk.', '["Wenn Sie einer isländischen staatlichen Institution eine Rechnung stellen, bestätigen Sie, dass diese elektronische Rechnungen über Fjársýsla ríkisins abwickelt, und reichen Sie entsprechend ein, statt per Papier oder PDF."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-b2g-municipal-2020', 'de', 'Gemeinden und öffentliche Unternehmen treten der Pflicht bei', 'Die Pflicht zum Empfang elektronischer Rechnungen wurde auf Gemeinden, ihre Einrichtungen, öffentliche Unternehmen und andere Einheiten mit besonderen Rechten oder Monopolen ausgeweitet und schloss damit den Rollout der Verordnung 44/2019 im gesamten isländischen öffentlichen Sektor ab.', '["Wenn Sie einer isländischen Gemeinde oder einem öffentlichen Unternehmen eine Rechnung stellen, bestätigen Sie, dass diese EN-16931-konforme E-Rechnungen empfangen kann, und prüfen Sie, ob Fjársýsla ríkisins oder ein eigener Peppol-Zugangspunkt genutzt wird."]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-b2g-2015', 'fr', 'Obligation ZOPSPU : le secteur public doit recevoir des factures électroniques', 'Depuis le 1er janvier 2015, le secteur public slovène est tenu de recevoir les factures exclusivement sous forme électronique, en vertu de la loi sur les services de paiement pour les utilisateurs budgétaires (ZOPSPU / ZOPSPU-A). UJP (l''Administration de la République de Slovénie pour les paiements publics) exploite le hub central obligatoire -- la « enotna vstopna in izstopna točka » (EVIT, point d''entrée et de sortie unique) -- par lequel les utilisateurs budgétaires échangent des factures électroniques, accessible via des banques participantes, des prestataires de traitement de données sous contrat, ou le portail e-Racuni propre à UJP pour les fournisseurs ne disposant ni de l''un ni de l''autre.', '["Vérifiez que votre entreprise soumet ses factures aux acheteurs du secteur public slovène par l''intermédiaire d''une banque, d''un prestataire sous contrat avec UJP, ou du portail e-Racuni d''UJP -- et non sur papier ou en simple PDF.", "Si vous facturez directement des utilisateurs budgétaires sans banque ni prestataire, inscrivez-vous pour obtenir l''accès au portail e-Racuni d''UJP."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-zierded-enacted', 'fr', 'Promulgation de la ZIERDED -- première loi slovène de facturation électronique B2B', 'La Zakon o izmenjavi elektronskih računov in drugih elektronskih dokumentov (ZIERDED) -- première loi slovène rendant obligatoire la facturation électronique B2B -- a été publiée au Journal officiel (Uradni list RS, št. 85/2025). Elle s''applique à toute entité inscrite au Registre du commerce slovène et à toute personne exerçant à titre indépendant (art. 7), instaure un déploiement en deux étapes (prestataires de voie électronique certifiés à partir du 1er avril 2027, obligation centrale d''échange à partir du 1er janvier 2028), et l''art. 1 rattache explicitement la loi à la transposition d''éléments de la directive ViDA de l''UE (2025/516).', '["Lisez le texte officiel de la ZIERDED pour comprendre lequel des trois canaux d''échange autorisés -- prestataire de voie électronique certifié, liaison directe système à système, ou Peppol -- convient à votre entreprise.", "Notez les deux échéances distinctes : le 1er avril 2027 pour la certification des prestataires de voie électronique, le 1er janvier 2028 pour l''obligation d''échange elle-même."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-epath-providers-2027', 'fr', 'Le régime des prestataires de "voie électronique" certifiés prend effet', 'Les règles du chapitre 4 de la ZIERDED relatives aux prestataires de voie électronique certifiés ("e-pot") s''appliquent à partir de cette date -- l''un des trois canaux autorisés, aux côtés de l''échange direct système à système et de Peppol, pour l''échange conforme de factures électroniques et de documents électroniques avant l''échéance de l''obligation générale du 1er janvier 2028.', '["Si vous prévoyez de recourir à un prestataire de voie électronique certifié plutôt qu''à Peppol ou à une liaison directe système à système, vérifiez que le prestataire choisi détient bien une certification au titre de ce régime avant de vous y fier."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('si-b2b-mandatory-2028', 'fr', 'Début de l''échange obligatoire de factures électroniques B2B', 'L''obligation centrale de la ZIERDED prend effet : toute entité inscrite au Registre du commerce slovène et toute personne exerçant à titre indépendant doit échanger des factures électroniques et d''autres documents électroniques via l''un des trois canaux autorisés par la loi -- prestataire de voie électronique certifié, liaison directe système à système, ou Peppol -- au format de la norme e-SLOG 2.0 (alignée sur EN 16931). Le non-respect de cette obligation entraîne des amendes au titre de l''art. 24 : 1 000-3 000 € pour les personnes morales, 500-1 500 € pour les entrepreneurs individuels, 100-500 € pour une personne responsable, avec une fourchette distincte et plus basse prévue à l''art. 25 pour les infractions relatives aux factures aux consommateurs.', '["Vérifiez que votre logiciel de facturation ou votre prestataire peut produire des factures électroniques conformes à e-SLOG 2.0 / EN 16931.", "Choisissez et testez l''un des trois canaux d''échange autorisés bien avant le 1er janvier 2028.", "Vérifiez que votre processus de comptes fournisseurs peut recevoir et traiter les factures électroniques entrantes via les mêmes canaux."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-reg44-2019', 'fr', 'Publication du règlement 44/2019', 'Le ministère islandais des Finances et des Affaires économiques (Fjármála- og efnahagsráðuneytið) a émis le règlement 44/2019 (reglugerð um rafræna reikninga vegna opinberra samninga), publié au journal officiel Stjórnartíðindi. Il transpose la directive 2014/55/UE de l''UE via l''appartenance de l''Islande à l''EEE, et exige que les acheteurs publics reçoivent et traitent des factures électroniques conformes à la norme européenne EN 16931.', '["Vérifiez si votre entreprise fournit des biens, des services ou des travaux à un organisme public islandais dans le cadre d''un contrat de marché public, de services publics, de concession, ou de défense/sécurité couvert par le règlement."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-b2g-state-2019', 'fr', 'Les institutions étatiques doivent recevoir des factures électroniques conformes à EN 16931', 'Les institutions étatiques islandaises ont été tenues de pouvoir recevoir et traiter des factures électroniques conformes à la norme européenne EN 16931. Fjársýsla ríkisins (l''Autorité de gestion financière) reçoit les factures électroniques pour le compte de la plupart des institutions étatiques, via le réseau Peppol.', '["Si vous facturez une institution étatique islandaise, vérifiez qu''elle achemine les factures électroniques via Fjársýsla ríkisins et soumettez-les en conséquence plutôt que sur papier ou en PDF."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('is-b2g-municipal-2020', 'fr', 'Les municipalités et les entreprises publiques rejoignent l''obligation', 'L''obligation de réception des factures électroniques a été étendue aux municipalités, à leurs institutions, aux entreprises publiques, et aux autres entités exerçant des droits spéciaux ou des monopoles, achevant ainsi le déploiement du règlement 44/2019 dans l''ensemble du secteur public islandais.', '["Si vous facturez une municipalité ou une entreprise publique islandaise, vérifiez qu''elle peut recevoir des factures électroniques conformes à EN 16931 et vérifiez si elle utilise Fjársýsla ríkisins ou son propre point d''accès Peppol."]');
